'use strict';
const Species=(()=>{
function kind(index){return (typeof ContentExpansion!=='undefined'&&ContentExpansion.raceTraits[index]?.kind)||(index>=15&&index<=22?'demon':index===23?'celestial':index===14?'undead':'mortal')}
const isDemon=index=>kind(index)==='demon';
const maturityAges=[18,70,60,55,32,20,18,17,30,48,24,15,12,22,40,38,42,32,44,52,35,36,30,48,18,21,14,20,36,16,65,50,34,46,28,75,120,90,36,22,30,34,44,24,52,42,38,15];
const maturity=index=>(typeof FrontierPeoples!=='undefined'?FrontierPeoples.maturity[index]:undefined)??maturityAges[index]??Math.max(18,RACES[index][2]*18/85);
const labels={mortal:'ผู้คนแห่งโลก',demon:'เผ่าปีศาจ',celestial:'สายเลือดดวงดาว',construct:'สิ่งสร้างมีชีวิต',undead:'ผู้ตื่นจากความตาย'};
return {kind,isDemon,maturity,label:index=>labels[kind(index)]||'ผู้คนแห่งโลก'};
})();
